/*白粉，不知道改哪里问ai，不想找ai找我也行，图标崩了找我，不要二转，二改仅自用*/

/* ========== A. 主题变量 ========== */

.chat-thread {

  --dress-chat-bg-overlay: transparent;

  --dress-header-bg: rgba(239, 239, 239, 0.85);

  --dress-header-blur: 16px;

  --dress-header-border: none;

  --dress-header-radius: 0px;

  --dress-header-shadow: none;

  --dress-header-title-color: var(--black);

  --dress-header-title-size: 16px;

  --dress-header-title-weight: 500;

  --dress-header-icon-color: var(--ink);

  --dress-bubble-me-bg: #FFF3F6;

  --dress-bubble-me-fg: #272727;

  --dress-bubble-me-border: none;

  --dress-bubble-me-shadow: none;

  --dress-bubble-me-radius: 4px;

  --dress-bubble-them-bg: #FFFFFF;

  --dress-bubble-them-fg: #272727;

  --dress-bubble-them-border: none;

  --dress-bubble-them-shadow: none;

  --dress-bubble-them-radius: 4px;

  --dress-compose-bar-bg: rgba(239, 239, 239, 0.85);

  --dress-compose-bar-fg: var(--ink);

  --dress-compose-bar-radius: 0px;

  --dress-compose-bar-border: none;

  --dress-compose-bar-shadow: none;

  --dress-compose-bar-blur: blur(18px);

  --dress-timestamp-color: var(--soft);

  --dress-scroll-pad-x: 14px;

}

html[data-theme="dark"] .chat-thread {

  --dress-header-bg: rgba(42, 42, 42, 0.92);

  --dress-header-border: none;

  --dress-header-shadow: none;

  --dress-header-title-color: #f0f0f0;

  --dress-header-icon-color: #f0f0f0;

  --dress-bubble-me-bg: #FFEDF4;

  --dress-bubble-me-fg: #272727;

  --dress-bubble-them-bg: #2e2e2e;

  --dress-bubble-them-fg: #efefef;

  --dress-bubble-them-shadow: none;

  --dress-compose-bar-bg: rgba(42, 42, 42, 0.92);

  --dress-compose-bar-border: none;

  --dress-compose-bar-shadow: none;

  --dress-timestamp-color: rgba(255, 255, 255, 0.55);

}

/* ========== B. 壳 ========== */

.chat-thread {

  background: var(--dress-chat-bg-overlay);

}

/* ========== C. 顶栏胶囊 ========== */

.chat-thread-pill {

  margin: 0 -20px;

  width: calc(100% + 40px);

  border-radius: 0;

  transform: translateY(-48px);

  padding-bottom: 34px;

  background: var(--dress-header-bg);

  border: 0.5px solid #d8d8d8;

  box-shadow: none;

  backdrop-filter: blur(var(--dress-header-blur));

  -webkit-backdrop-filter: blur(var(--dress-header-blur));

  color: var(--dress-header-icon-color);

}

.chat-back,

.chat-back-wrap {

  color: var(--dress-header-icon-color);

  display: inline-block !important;

  transform: translate(-10px, 35px) scale(1.2) !important;

  transform-origin: left center !important;

}

.chat-thread-center h2 {

  color: var(--dress-header-title-color);

  font-size: 16px;

  font-weight: var(--dress-header-title-weight);

  transform: translateY(35px);

  display: inline-block;

}

.chat-thread-head-xinsheng {

  color: var(--dress-header-icon-color);

  display: inline-block !important;

  transform: translateY(35px);

}

.chat-thread-head-more {

  color: var(--dress-header-icon-color);

  display: inline-block !important;

  transform: translate(-15px, 35px) scale(0.45) !important;

  transform-origin: right center !important;

}

/* ========== D. 头像 / 昵称 ========== */

.chat-ava,

.chat-ava-sm {

  width: 34px !important;

  height: 34px !important;

  align-self: flex-start;

  margin-top: 0 !important;

  border: none !important;

  box-shadow: none !important;

  border-radius: 4px !important;

}

.chat-msg-name {

  font-size: 11px;

  opacity: 0.72;

}

.chat-msg.is-them .chat-msg-name {

  display: none !important;

}

/* ========== E. 气泡 ========== */

.chat-msg,

.chat-msg-body,

.chat-swipe-host,

.chat-swipe-content,

.chat-longpress-host {

  overflow: visible !important;

}

/* 让消息体变为纵向排列，以便调整气泡和引用框的上下顺序 */

.chat-msg-body {

  display: flex !important;

  flex-direction: column !important;

}

/* 对方消息：左对齐 */

.chat-msg.is-them .chat-msg-body {

  align-items: flex-start !important;

}

/* 我方消息：右对齐 */

.chat-msg.is-me .chat-msg-body {

  align-items: flex-end !important;

}

.chat-bubble {

  order: 1 !important; /* 正常聊天主气泡排在上方 */

  font-size: 14px !important;

  line-height: 1.45;

  min-height: 34px !important;

  box-sizing: border-box !important;

  display: inline-flex !important;

  align-items: center;

  border: none;

  box-shadow: none;

  padding-top: 6px !important;

  padding-bottom: 6px !important;

  padding-left: calc(var(--bubble-padding-x, 12px) - 2px) !important;

  padding-right: calc(var(--bubble-padding-x, 12px) - 2px) !important;

  white-space: normal;

  word-break: normal;

  overflow-wrap: break-word;

  position: relative;

  overflow: visible !important;

}

.chat-msg.has-sticker .chat-msg-body,

.chat-msg.has-image .chat-msg-body {

  white-space: normal;

  word-break: normal;

  overflow-wrap: normal;

}

/* =====================================================

   【气泡尾巴】

   ===================================================== */

.chat-msg.is-me .chat-bubble::after {

  content: '';

  position: absolute;

  right: -6px;

  top: 12px;

  width: 11px;

  height: 11px;

  background: url('https://i.postimg.cc/fRvFh3y7/wu-biao-ti281-20260912083007.png') center / contain no-repeat;

  background-size: contain;

  pointer-events: none;

  z-index: 99;

}

.chat-msg.is-them .chat-bubble::after {

  content: '';

  position: absolute;

  left: -6px;

  top: 12px;

  width: 11px;

  height: 11px;

  background: url('https://i.postimg.cc/3xxRtSqT/wu-biao-ti98-20260526052653.png') center / contain no-repeat;

  background-size: contain;

  pointer-events: none;

  z-index: 99;

}

/* ========== F-K. 空壳保留 / 引用气泡定制 ========== */

.chat-msg-time {

  display: none !important;

}

/* ★ 居中时间戳：单独小气泡包裹，样式和引用气泡一致 */

.chat-msg-timestamp {

  display: block !important;

  width: fit-content !important;

  margin: 12px auto !important;

  padding: 3px 7px !important;

  background-color: #F7F7F7 !important;

  border: 0.4px solid #C8C8C8 !important;

  border-radius: 4px !important;

  color: #707070 !important;

  font-size: 12px !important;

  line-height: 1.2 !important;

  text-align: center !important;

  box-shadow: none !important;

  box-sizing: border-box !important;

}

.chat-recall-wrap,

.chat-recall-row {

  text-align: center !important;

  margin: 12px auto !important;

  position: relative !important;

}

.chat-recall-text {

  display: inline-block !important;

  padding: 3px 7px !important;

  background-color: #F7F7F7 !important;

  border: 0.4px solid #C8C8C8 !important;

  border-radius: 4px !important;

  color: #707070 !important;

  font-size: 12px !important;

  line-height: 1.2 !important;

  box-shadow: none !important;

  box-sizing: border-box !important;

}

.chat-recall-view {

  position: absolute !important;

  opacity: 0 !important;

  pointer-events: auto !important;

}

.chat-thread-notice-wrap {}

.chat-thread-notice {}

/* =====================================================

   【引用气泡定制】

   ===================================================== */

/* 1. 给包含引用的主气泡底部增加外边距，防止"拔"出来的引用框遮挡下一条消息 */

.chat-bubble:has(.chat-qq-quote) {

  margin-bottom: 40px !important; 

}

/* 2. 核心：将引用框彻底脱离主气泡包裹，强行移到正下方独立显示 */

.chat-qq-quote {

  position: absolute !important;

  top: 100% !important;

  margin-top: 6px !important;

  display: flex !important;

  flex-direction: row !important;

  align-items: center !important;

  background-color: #F7F7F7 !important;

  color: #707070 !important;

  border: 0.4px solid #C8C8C8 !important;

  border-radius: 4px !important;

  padding: 3px 7px !important;

  box-shadow: none !important;

  width: max-content !important;

  max-width: 250px !important;

  box-sizing: border-box !important;

  white-space: nowrap !important;

  overflow: hidden !important;

  text-overflow: ellipsis !important;

  z-index: 10 !important;

  font-size: 12px !important;

  line-height: 1.2 !important;

}

.chat-qq-quote,

.chat-qq-quote * {

  color: #707070 !important;

}

/* 3. 去除某些主题用伪元素画的备用竖线 I */

.chat-qq-quote::before {

  display: none !important;

  content: none !important;

}

/* 4. 我方消息：引用气泡吸附在右侧对齐 */

.chat-msg.is-me .chat-qq-quote {

  right: 0 !important;

}

/* 5. 对方消息：引用气泡吸附在左侧对齐 */

.chat-msg.is-them .chat-qq-quote {

  left: 0 !important;

}

/* 6. 确保名字和文字强行同行且超出部分显示省略号 */

.chat-qq-quote > * {

  white-space: nowrap !important;

  overflow: hidden !important;

  text-overflow: ellipsis !important;

  display: inline-block !important;

  font-size: inherit !important;

  color: inherit !important;

}

/* 名字不被压缩 */

.chat-qq-quote > *:first-child {

  flex-shrink: 0 !important;

}

/* 文字太长时允许被压缩并显示省略号 */

.chat-qq-quote > *:last-child {

  flex-shrink: 1 !important;

}

/* 7. 在引用名字右侧加 : */

.chat-qq-quote-name::after,

.chat-qq-quote .name::after,

.chat-qq-quote > span:first-child::after {

  content: " : " !important;

  margin-right: 4px !important;

}

/* =====================================================

   【翻译卡片定制】白底卡片 + 大图标左下角伸出

   ===================================================== */

/* 1. 有翻译的对方气泡：本身上下padding强制压回6px */

.chat-msg.is-them .chat-bubble:has(.chat-bubble-trans-inline),

.chat-msg.is-them .chat-bubble:has(.chat-bubble-trans-chip) {

  padding-top: 6px !important;

  padding-bottom: 6px !important;

  min-height: 34px !important;

  height: auto !important;

}

/* 2. 气泡内所有元素通杀--上下padding/margin/min-height清零（翻译元素本身除外） */

.chat-msg.is-them .chat-bubble:has(.chat-bubble-trans-inline) *:not(.chat-bubble-trans-inline):not(.chat-bubble-trans-chip),

.chat-msg.is-them .chat-bubble:has(.chat-bubble-trans-chip) *:not(.chat-bubble-trans-inline):not(.chat-bubble-trans-chip) {

  padding-top: 0 !important;

  padding-bottom: 0 !important;

  margin-top: 0 !important;

  margin-bottom: 0 !important;

  min-height: 0 !important;

}

/* 3. 主气泡底部留白50px */

.chat-msg.is-them:has(.chat-bubble-trans-inline) .chat-msg-body,

.chat-msg.is-them:has(.chat-bubble-trans-chip) .chat-msg-body {

  padding-bottom: 50px !important;

}

/* 4. 翻译卡片：白底，padding上6/右10/下25/左10，最小宽120最大宽250 */

.chat-msg.is-them .chat-bubble .chat-bubble-trans-inline {

  position: absolute !important;

  top: 100% !important;

  left: 0 !important;

  margin-top: 6px !important;

  background: #FFFFFF !important;

  border: none !important;

  box-shadow: none !important;

  border-radius: 4px !important;

  padding: 6px 10px 25px 10px !important;

  min-width: 120px !important;

  max-width: 250px !important;

  opacity: 1 !important;

  z-index: 10 !important;

  font-size: 12px !important;

  line-height: 1.45 !important;

  color: #1A1A1A !important;

  box-sizing: border-box !important;

  white-space: normal !important;

  word-break: break-word !important;

  pointer-events: none !important;

}

/* 4.1 暗色模式：翻译卡片深色背景 */

html[data-theme="dark"] .chat-msg.is-them .chat-bubble .chat-bubble-trans-inline {

  background: #2e2e2e !important;

  color: #efefef !important;

}

/* 4.2 左下角大图标：110x110，left:8px bottom:-40px（底部40px伸出卡片外） */

.chat-msg.is-them .chat-bubble .chat-bubble-trans-inline::before {

  content: '' !important;

  position: absolute !important;

  left: 6px !important;

  bottom: -40px !important;

  width: 110px !important;

  height: 110px !important;

  background: url('https://i.postimg.cc/0Qphq7xs/Screenshot-2026-09-12-20-25-18-32-e39d2c7de19156b0683cd93e8735f348.jpg') center / contain no-repeat !important;

}

/* 5. 翻译标签/芯片：保持在气泡下方，透明 */

.chat-msg.is-them .chat-bubble-trans-chip {

  position: absolute !important;

  top: 100% !important;

  left: 0 !important;

  margin-top: 4px !important;

  background: transparent !important;

  border: none !important;

  box-shadow: none !important;

  padding: 0 !important;

  opacity: 0.7 !important;

  z-index: 10 !important;

  font-size: 12px !important;

  line-height: 1.35 !important;

  pointer-events: none !important;

}

/* 6. "翻译"标签文字弱化 */

.chat-msg.is-them .chat-bubble-trans-chip-label {

  font-size: 10px !important;

  opacity: 0.5 !important;

  margin-right: 4px !important;

}

/* 7. 翻译内子元素：透明背景、无边框、继承卡片文字色 */

.chat-msg.is-them .chat-bubble .chat-bubble-trans-inline * {

  background: transparent !important;

  border: none !important;

  box-shadow: none !important;

  color: inherit !important;

}

/* 8. 对方气泡内部所有容器允许溢出 */

.chat-msg.is-them .chat-bubble,

.chat-msg.is-them .chat-bubble * {

  overflow: visible !important;

}

/* ========== L. 输入胶囊 ========== */

.chat-compose-bar {

  margin: 0 -20px;

  width: calc(100% + 40px);

  border-radius: 0;

  transform: translateY(25px);

  padding-top: 32px;

  border: 0.5px solid #d8d8d8;

  box-shadow: none;

}

.chat-compose-input {

  background-color: #ffffff;

  border-radius: 4px;

  transform: translate(8px, -25px);

  padding-top: 6px !important;

  padding-bottom: 6px !important;

  min-height: unset !important;

  width: calc(100% - 110px) !important;

  max-width: calc(100% - 110px) !important;

  min-width: 0 !important;

  flex: 0 0 auto !important;

  margin-right: 0 !important;

  padding-right: 40px !important;

}

.chat-compose-input::placeholder {

  color: transparent;

}

.chat-compose-plus,

.chat-compose-icon {

  width: 25px !important;

  height: 25px !important;

  transform: translate(7px, -28px);

}

/* 【低栏位置·发送键】 */

.chat-compose-icon.is-send,

.chat-compose-icon.is-send.ready {

  width: 26px !important;

  height: 26px !important;

  transform: translate(-5px, -34px) !important;

  display: inline-flex !important;

  opacity: 1 !important;

  visibility: visible !important;

  pointer-events: auto !important;

}

.chat-compose-icon.is-reply {

  width: 25px !important;

  height: 25px !important;

  transform: translate(-12px, -28px) !important;

  position: relative;

}

.chat-compose-icon.is-voice {

  width: 16px !important;

  height: 16px !important;

  transform: translate(-20px, -32px) !important;

  z-index: 10;

}

.chat-compose-icon.is-reply::after {

  content: '';

  display: inline-block;

  width: 25px;

  height: 25px;

  background: url('https://i.postimg.cc/4dWF7m8S/wu-biao-ti139-20260610060854.png') center / contain no-repeat;

  position: absolute;

  left: calc(100% + 8px);

  top: 50%;

  transform: translateY(-50%);

}

/* ========== N. 自定义图标替换 ========== */

.chat-back-wrap {

  background: url('https://i.postimg.cc/8knbqr4C/retouch-2026052418550015.png') center / contain no-repeat !important;

}

.chat-back-wrap > * { display: none !important; }

.chat-thread-head-xinsheng {

  background: url('https://i.postimg.cc/Gp7Qd8Rg/wu-biao-ti93-20260524183244.png') center / contain no-repeat !important;

}

.chat-thread-head-xinsheng > * { display: none !important; }

.chat-thread-head-more {

  background: url('https://i.postimg.cc/CM64Wf7B/retouch-2026052418551123.png') center / contain no-repeat !important;

}

.chat-thread-head-more > * { display: none !important; }

.chat-compose-plus {

  background: url('https://i.postimg.cc/t4HRyvXZ/retouch-2026061605235276.png') center / contain no-repeat !important;

}

.chat-compose-plus > * { display: none !important; }

.chat-compose-icon.is-voice {

  background: url('https://i.postimg.cc/SxpQq1yJ/retouch-2026061605240779.png') center / contain no-repeat !important;

}

.chat-compose-icon.is-voice > * { display: none !important; }

.chat-compose-icon.is-reply {

  background: url('https://i.postimg.cc/dtCQbcKy/retouch-2026061605242348.png') center / contain no-repeat !important;

}

.chat-compose-icon.is-reply > * { display: none !important; }

/* ★发送键图标替换 */

.chat-compose-icon.is-send,

.chat-compose-icon.is-send.ready {

  background: url('https://i.postimg.cc/Gp7Qd8Rg/wu-biao-ti93-20260524183244.png') center / contain no-repeat !important;

}

.chat-compose-icon.is-send > *,

.chat-compose-icon.is-send.ready > * { display: none !important; }

