/* ========== A. 主题变量 ========== */

.chat-thread {

  --dress-chat-bg-overlay: transparent;

  --dress-header-bg: rgba(241, 241, 241, 0.85);

  --dress-header-blur: 16px;

  --dress-header-border: none;

  --dress-header-radius: 0px;

  --dress-header-shadow: none;

  --dress-header-title-color: var(--black);

  --dress-header-title-size: 16px;

  --dress-header-title-weight: 500;

  --dress-header-icon-color: var(--ink);

  --dress-bubble-me-bg: #050505;

  --dress-bubble-me-fg: #FDFDFD;

  --dress-bubble-me-border: none;

  --dress-bubble-me-shadow: none;

  --dress-bubble-me-radius: 10px;

  --dress-bubble-them-bg: #FFFFFF;

  --dress-bubble-them-fg: #1A1A1A;

  --dress-bubble-them-border: none;

  --dress-bubble-them-shadow: none;

  --dress-bubble-them-radius: 10px;

  --dress-compose-bar-bg: rgba(241, 241, 241, 0.85);

  --dress-compose-bar-fg: var(--ink);

  --dress-compose-bar-radius: 0px;

  --dress-compose-bar-border: none;

  --dress-compose-bar-shadow: none;

  --dress-compose-bar-blur: blur(18px);

  --dress-scroll-pad-x: 14px;

}

html[data-theme="dark"] .chat-thread {

  --dress-header-bg: rgba(42, 42, 42, 0.92);

  --dress-header-border: none;

  --dress-header-shadow: none;

  --dress-header-title-color: #f0f0f0;

  --dress-header-icon-color: #f0f0f0;

  --dress-bubble-me-bg: #050505;

  --dress-bubble-me-fg: #FDFDFD;

  --dress-bubble-them-bg: #2e2e2e;

  --dress-bubble-them-fg: #efefef;

  --dress-bubble-them-shadow: none;

  --dress-compose-bar-bg: rgba(42, 42, 42, 0.92);

  --dress-compose-bar-border: none;

  --dress-compose-bar-shadow: none;

}

/* ========== B. 壳 ========== */

.chat-thread {

  background: var(--dress-chat-bg-overlay);

}

/* ========== C. 顶栏 ========== */

.chat-thread-pill {

  margin: 0 -20px;

  width: calc(100% + 40px);

  border-radius: 0;

  transform: translateY(-48px);

  padding-bottom: 43px;

  background: var(--dress-header-bg);

  border: none !important;

  box-shadow: none;

  backdrop-filter: blur(var(--dress-header-blur));

  -webkit-backdrop-filter: blur(var(--dress-header-blur));

  color: var(--dress-header-icon-color);

}

/* ===== 返回键 ===== */

.chat-back,

.chat-back-wrap {

  color: var(--dress-header-icon-color);

  display: inline-block !important;

  /*

    返回键位置：

    translate(左右, 上下)

    第一个数字：

    正数 = 向右

    负数 = 向左

    第二个数字：

    正数 = 向下

    负数 = 向上

    scale(1.5) = 图标大小

    数字越大 = 越大

  */

  transform: translate(-12px, 40px) scale(1.5) !important;

  transform-origin: left center !important;

}

/* ===== 顶栏：99+ / 名字 / 右侧图片 ===== */

.chat-thread-center {

  position: absolute !important;

  /*

    这里的 left 控制整组内容的左右位置。

    数字越大 = 整组向右

    数字越小 = 整组向左

  */

  left: 42px !important;

  /*

    top 控制整组内容的上下位置。

    数字越大 = 向下

    数字越小 = 向上

  */

  top: 0 !important;

  width: auto !important;

  text-align: left !important;

  display: inline-flex !important;

  align-items: center !important;

  gap: 7px !important;

  /*

    整组上下微调：

    正数 = 向下

    负数 = 向上

  */

  transform: translateY(35px) !important;

}

/* ===== 99+ ===== */

.chat-thread-center::before {

  content: "99+";

  display: inline-flex;

  align-items: center;

  justify-content: center;

  background: #D8D8D8;

  border-radius: 16px;

  font-size: 12px;

  font-weight: 500;

  line-height: 1;

  padding: 5px 6px;

  color: #1A1A1A;

  white-space: nowrap;

  /*

    99+ 位置：

    第一个 = 左右

    第二个 = 上下

    正数左右 = 向右

    负数左右 = 向左

    正数上下 = 向下

    负数上下 = 向上

  */

  transform: translate(-13px, -27px) !important;

}

/* ===== 顶栏名字 ===== */

.chat-thread-center h2 {

  color: var(--dress-header-title-color);

  font-size: 17px;

  font-weight: var(--dress-header-title-weight);

  display: inline-block;

  margin: 0 !important;

  text-align: left !important;

  line-height: 1;

  /*

    名字位置：

    第一个 = 左右

    第二个 = 上下

  */

  transform: translate(-13px, -27px) !important;

}

/* ===== 名字右侧图片 ===== */

.chat-thread-center::after {

  content: '';

  display: inline-block;

  /*

    图片大小：

    width = 横向大小

    height = 纵向大小

    两个一起改可以保持比例。

  */

  width: 110px;

  height: 110px;

  background: url('https://i.postimg.cc/tgzD9zHP/IMG-20260917-101110.png') center / contain no-repeat;

