    图片位置：

    第一个 = 左右

    第二个 = 上下

  */

  transform: translate(-16px, -33px) !important;

}

/* ===== 顶栏「线下模式」图标 ===== */

.chat-thread-head-xinsheng {

  color: var(--dress-header-icon-color);

