  background: url('https://i.postimg.cc/Gp7Qd8Rg/wu-biao-ti93-20260524183244.png') center / contain no-repeat !important;

}

.chat-compose-icon.is-reply > * {

  display: none !important;

}

.chat-compose-icon.is-send,

.chat-compose-icon.is-send.ready {

  background: url('https://i.postimg.cc/Gp7Qd8Rg/wu-biao-ti93-20260524183244.png') center / contain no-repeat !important;

}

.chat-compose-icon.is-send > *,

.chat-compose-icon.is-send.ready > * {

  display: none !important;

}

/* ========== I. 翻译文字（清晰高清防糊版） ========== */

/* 1. 含翻译的气泡 */

.chat-msg .chat-bubble:has(.chat-bubble-trans-inline) {

  background: transparent !important;

  box-shadow: none !important;

  padding: 0 !important;

  display: flex !important;

  flex-direction: column !important;

  gap: 0 !important;

}

.chat-msg.is-them .chat-bubble:has(.chat-bubble-trans-inline) {

  align-items: flex-start !important;

}

.chat-msg.is-me .chat-bubble:has(.chat-bubble-trans-inline) {

  align-items: flex-end !important;

}

/* 2. 隐藏翻译以外的中间占位元素 */

.chat-msg .chat-bubble:has(.chat-bubble-trans-inline) > *:not(.chat-bubble-trans-inline):not(.chat-qq-quote) {

  background: transparent !important;

  padding: 0 !important;

  margin: 0 !important;

  height: 0 !important;

  overflow: hidden !important;

  border: none !important;

}

/* 3. 恢复正文气泡高度和样式 */

.chat-msg.is-them .chat-bubble:has(.chat-bubble-trans-inline) > :nth-child(1):not(.chat-qq-quote),

.chat-msg.is-them .chat-bubble:has(.chat-bubble-trans-inline) > .chat-qq-quote + *,

.chat-msg.is-me .chat-bubble:has(.chat-bubble-trans-inline) > :nth-child(1):not(.chat-qq-quote),

.chat-msg.is-me .chat-bubble:has(.chat-bubble-trans-inline) > .chat-qq-quote + * {

  min-height: 34px !important;

  display: inline-flex !important;

  align-items: center !important;

  box-sizing: border-box !important;

  padding: 6px calc(var(--bubble-padding-x, 12px) - 2px) !important;

  border-radius: 10px !important;

  width: fit-content !important;

  height: auto !important;

  overflow: visible !important;

}

.chat-msg.is-them .chat-bubble:has(.chat-bubble-trans-inline) > :nth-child(1):not(.chat-qq-quote),

.chat-msg.is-them .chat-bubble:has(.chat-bubble-trans-inline) > .chat-qq-quote + * {

  background: var(--dress-bubble-them-bg, #FFFFFF) !important;

  color: var(--dress-bubble-them-fg, #1A1A1A) !important;

}

.chat-msg.is-me .chat-bubble:has(.chat-bubble-trans-inline) > :nth-child(1):not(.chat-qq-quote),

.chat-msg.is-me .chat-bubble:has(.chat-bubble-trans-inline) > .chat-qq-quote + * {

  background: var(--dress-bubble-me-bg, #050505) !important;

  color: var(--dress-bubble-me-fg, #FDFDFD) !important;

}

/* 4. 翻译文字本体 */

.chat-msg .chat-bubble .chat-bubble-trans-inline {

  position: relative !important;

  top: auto !important;

  left: auto !important;

  /*

    翻译上下位置：margin-top: -12px

    更接近 0 = 翻译往下

    更小的负数 = 翻译往上

  */

  transform: none !important;

  margin: -12px 0 0 0 !important;

  background: transparent !important;

  border: none !important;

  border-radius: 0 !important;

  padding: 2px 4px !important;

  min-width: unset !important;

  width: fit-content !important;

  max-width: 250px !important;

  box-shadow: none !important;

  z-index: 10 !important;

  font-size: 12px !important;

  line-height: 1.45 !important;

  -webkit-text-stroke: 0 !important;

  color: #FFFFFF !important;

  font-weight: 600 !important;

  text-shadow:

    0px 0px 2px rgba(0, 0, 0, 0.9),

    0px 1px 2px rgba(0, 0, 0, 0.8) !important;

  box-sizing: border-box !important;

  white-space: normal !important;

  word-break: break-word !important;

  height: auto !important;

  overflow: visible !important;

}

/* 5. 暗色模式适配 */

html[data-theme="dark"] .chat-msg .chat-bubble .chat-bubble-trans-inline {

  background: transparent !important;

  color: #FFFFFF !important;

}

/* 6. 隐藏系统自带小标签 */

.chat-msg .chat-bubble-trans-chip {

  display: none !important;

}

/* 7. 翻译消息与下一条消息的间距 */

.chat-msg:has(.chat-bubble-trans-inline) {

  margin-bottom: 6px !important;

}
